1	/**
2	 * @module BatchList
3	 *
4	 * Gestão de lotes (batches) de produtos no estoque.
5	 * Permite criar novos lotes, ajustar quantidades com debounce,
6	 * excluir lotes e exibe status de validade com cores.
7	 */
8	
9	import React, { useState, useEffect } from 'react';
10	import {
11	  Plus,
12	  AlertTriangle,
13	  Calendar,
14	  Package,
15	  Minus,
16	} from 'lucide-react';
17	import { Button } from '@/shared/ui/button';
18	import { Input } from '@/shared/ui/input';
19	import { Badge } from '@/shared/ui/badge';
20	import { Popover, PopoverContent, PopoverTrigger } from '@/shared/ui/popover';
21	import { Calendar as CalendarComponent } from '@/shared/ui/calendar';
22	import { format, addDays, parseISO } from 'date-fns';
23	import { cn } from '@/shared/lib/utils';
24	import { supabase } from '@/integrations/supabase/client';
25	import { useToast } from '@/shared/hooks/use-toast';
26	
27	interface BatchData {
28	  id: string; // lote_id
29	  codigo: string;
30	  validade: string;
31	  fabricacao: string | null;
32	}
33	
34	interface StockBatch {
35	  id: string; // estoque_lotes id
36	  lote_id: string;
37	  quantidade: number;
38	  lotes: BatchData;
39	}
40	
41	interface BatchListProps {
42	  produtoId: number;
43	  storeId: number;
44	  produtoNome: string;
45	  diasValidadePadrao?: number;
46	  onUpdate?: () => void;
47	}
48	
49	/**
50	 * Lista e gerencia lotes de um produto em uma loja específica.
51	 * Permite criar lotes com datas de fabricação/validade, ajustar quantidades
52	 * (com debounce de 1s e registro de movimentação) e excluir lotes.
53	 *
54	 * @param produtoId - ID do produto master.
55	 * @param storeId - ID da loja no estoque.
56	 * @param produtoNome - Nome do produto (para exibição).
57	 * @param diasValidadePadrao - Dias de validade padrão para auto-preencher data.
58	 * @param onUpdate - Callback chamado após qualquer alteração nos lotes.
59	 */
60	export function BatchList({
61	  produtoId,
62	  storeId,
63	  produtoNome,
64	  diasValidadePadrao,
65	  onUpdate,
66	}: BatchListProps) {
67	  const [batches, setBatches] = useState<StockBatch[]>([]);
68	  const [loading, setLoading] = useState(false);
69	  const pendingUpdates = React.useRef<Record<string, number>>({});
70	  const updateTimeouts = React.useRef<Record<string, number>>({});
71	
72	  // New Batch Form
73	  const [newFabricacao, setNewFabricacao] = useState<Date | undefined>(
74	    new Date(),
75	  );
76	  const [newValidade, setNewValidade] = useState<Date | undefined>(
77	    diasValidadePadrao ? addDays(new Date(), diasValidadePadrao) : undefined,
78	  );
79	  const [newQtd, setNewQtd] = useState('');
80	  const [isAdding, setIsAdding] = useState(false);
81	
82	  const { toast } = useToast();
83	
84	  useEffect(() => {
85	    fetchBatches();
86	    // eslint-disable-next-line react-hooks/exhaustive-deps
87	  }, [produtoId, storeId]);
88	
89	  useEffect(() => {
90	    if (newFabricacao && diasValidadePadrao) {
91	      setNewValidade(addDays(newFabricacao, diasValidadePadrao));
92	    }
93	  }, [newFabricacao, diasValidadePadrao]);
94	
95	  const fetchBatches = async () => {
96	    setLoading(true);
97	    try {
98	      const { data, error } = await supabase
99	        .from('estoque_lotes' as any)
100	        .select(
101	          `
102	                    id,
103	                    lote_id,
104	                    quantidade,
105	                    lotes (
106	                        id,
107	                        codigo,
108	                        data_validade,
109	                        data_fabricacao
110	                    )
111	                `,
112	        )
113	        .eq('produto_id', produtoId)
114	        .eq('loja_id', storeId);
115	
116	      if (error) throw error;
117	
118	      // Caixa vazia (qtd 0) "some" da tela — saldo zerado não é caixa.
119	      const visiveis = ((data || []) as any[]).filter(
120	        (r) => Number(r.quantidade) > 0,
121	      );
122	      const sorted = visiveis.sort((a, b) => {
123	        const dateA = new Date(a.lotes.data_validade).getTime();
124	        const dateB = new Date(b.lotes.data_validade).getTime();
125	        return dateA - dateB;
126	      });
127	
128	      setBatches(sorted);
129	    } catch (error) {
130	      console.error('Error fetching batches:', error);
131	    } finally {
132	      setLoading(false);
133	    }
134	  };
135	
136	  const handleAddBatch = async () => {
137	    if (!newFabricacao || !newValidade || !newQtd) {
138	      toast({ title: 'Preencha todos os campos', variant: 'destructive' });
139	      return;
140	    }
141	
142	    const fabricacaoStr = format(newFabricacao, 'ddMMyyyy');
143	    // Código padrão 9 chars (L+ddMMyyyy) — sem HHmm, pra não divergir do mesmo lote físico.
144	    const generatedLoteCode = `L${fabricacaoStr}`;
145	
146	    try {
147	      // Criação idempotente: reaproveita o lote existente em vez de criar id divergente.
148	      const { data: loteId, error: loteError } = await (supabase.rpc as any)('find_or_create_lote', {
149	        p_produto_id: produtoId,
150	        p_codigo: generatedLoteCode,
151	        p_data_validade: format(newValidade, 'yyyy-MM-dd'),
152	        p_data_fabricacao: format(newFabricacao, 'yyyy-MM-dd'),
153	        p_loja_id: storeId,
154	      });
155	
156	      if (loteError) throw loteError;
157	
158	      const { error: stockError } = await supabase
159	        .from('estoque_lotes' as any)
160	        .insert({
161	          loja_id: storeId,
162	          produto_id: produtoId,
163	          lote_id: loteId,
164	          quantidade: parseFloat(newQtd),
165	        });
166	
167	      if (stockError) throw stockError;
168	
169	      toast({ title: `Lote ${generatedLoteCode} criado com sucesso!` });
170	
171	      setNewQtd('');
172	      setNewFabricacao(new Date());
173	      setIsAdding(false);
174	
175	      fetchBatches();
176	      onUpdate?.();
177	    } catch (e: any) {
178	      console.error(e);
179	      toast({
180	        title: 'Erro ao criar lote',
181	        description: e.message || 'Verifique os dados e tente novamente',
182	        variant: 'destructive',
183	      });
184	    }
185	  };
186	
187	  // Tudo flui por uma RPC atômica: nada de UPDATE direto em estoque_lotes
188	  // (que disparava o reconciliador 'sync_lote_auto' fantasma). A RPC insere a
189	  // movimentação e os triggers sincronizam estoque + estoque_lotes coerentes.
190	  const processBatchUpdate = async (
191	    stockBatchId: string,
192	    deltaTotal: number,
193	    loteId: string,
194	  ) => {
195	    try {
196	      if (deltaTotal !== 0) {
197	        const { data, error } = await (supabase.rpc as any)(
198	          'ajustar_lote_contagem',
199	          {
200	            p_lote_id: loteId,
201	            p_produto_master_id: produtoId,
202	            p_loja_id: storeId,
203	            p_delta: deltaTotal,
204	            p_motivo: 'ajuste_lote_manual',
205	            p_observacoes: 'Ajuste manual de lote (contagem)',
206	          },
207	        );
208	        if (error) throw error;
209	        if (data && (data as any).ok === false) {
210	          throw new Error((data as any).erro || 'Falha ao ajustar lote');
211	        }
212	      }
213	
214	      onUpdate?.();
215	    } catch (e: any) {
216	      console.error('Error processing batch update:', e);
217	      toast({
218	        title: 'Erro ao salvar alterações',
219	        description: e.message,
220	        variant: 'destructive',
221	      });
222	      fetchBatches();
223	    } finally {
224	      delete pendingUpdates.current[stockBatchId];
225	      delete updateTimeouts.current[stockBatchId];
226	    }
227	  };
228	
229	  const adjustQuantity = (
230	    stockBatchId: string,
231	    currentQtd: number,
232	    delta: number,
233	    loteId: string,
234	  ) => {
235	    const newQ = Math.max(0, currentQtd + delta);
236	    const effectiveDelta = newQ - currentQtd;
237	
238	    if (effectiveDelta === 0) return;
239	
240	    setBatches((prev) =>
241	      prev.map((b) => (b.id === stockBatchId ? { ...b, quantidade: newQ } : b)),
242	    );
243	
244	    if (updateTimeouts.current[stockBatchId]) {
245	      clearTimeout(updateTimeouts.current[stockBatchId]);
246	    }
247	
248	    const currentDelta = pendingUpdates.current[stockBatchId] || 0;
249	    const nextDelta = parseFloat((currentDelta + effectiveDelta).toFixed(4));
250	    pendingUpdates.current[stockBatchId] = nextDelta;
251	
252	    updateTimeouts.current[stockBatchId] = setTimeout(() => {
253	      const finalDelta = pendingUpdates.current[stockBatchId];
254	      processBatchUpdate(stockBatchId, finalDelta, loteId);
255	    }, 1000);
256	  };
257	
258	  // Sem exclusão de lote/caixa: a caixa só se MOVE (entrada/saída). Para "tirar"
259	  // o saldo, ajuste para 0 — a caixa vazia some da lista (filtro em fetchBatches).
260	
261	  const getExpiryStatus = (dateStr: string) => {
262	    const today = new Date();
263	    const expiry = parseISO(dateStr);
264	    const daysUntil = (expiry.getTime() - today.getTime()) / (1000 * 3600 * 24);
265	
266	    if (daysUntil < 0)
267	      return {
268	        color: 'text-red-600 bg-red-50 border-red-200',
269	        label: 'Vencido',
270	        icon: AlertTriangle,
271	      };
272	    if (daysUntil < 30)
273	      return {
274	        color: 'text-orange-600 bg-orange-50 border-orange-200',
275	        label: 'Vence em breve',
276	        icon: AlertTriangle,
277	      };
278	    return {
279	      color: 'text-green-600 bg-green-50 border-green-200',
280	      label: 'Ok',
281	      icon: Calendar,
282	    };
283	  };
284	
285	  return (
286	    <div className="w-full bg-white/40 dark:bg-black/20 rounded-xl border border-[#57715B]/10 p-4 space-y-4">
287	      <div className="flex items-center justify-between">
288	        <h4 className="text-sm font-bold text-[#57715B] dark:text-[#E6DCCF] uppercase tracking-wider flex items-center gap-2">
289	          <Package className="w-4 h-4" /> Gestão de Lotes
290	        </h4>
291	        <Button
292	          variant="outline"
293	          size="sm"
294	          onClick={() => setIsAdding(!isAdding)}
295	          className="h-7 text-xs gap-1 border-[#57715B]/30 text-[#57715B] hover:bg-[#57715B]/10"
296	        >
297	          <Plus className="w-3 h-3" /> {isAdding ? 'Cancelar' : 'Novo Lote'}
298	        </Button>
299	      </div>
300	
301	      {isAdding && (
302	        <div className="bg-white/60 dark:bg-black/40 p-3 rounded-lg border border-[#57715B]/10 space-y-3 animate-in slide-in-from-top-2">
303	          <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
304	            <Popover>
305	              <PopoverTrigger asChild>
306	                <Button
307	                  variant="outline"
308	                  className={cn(
309	                    'h-8 text-xs justify-start text-left font-normal',
310	                    !newFabricacao && 'text-muted-foreground',
311	                  )}
312	                >
313	                  <Calendar className="mr-2 h-3 w-3" />
314	                  {newFabricacao
315	                    ? format(newFabricacao, 'dd/MM/yyyy')
316	                    : 'Fabricação'}
317	                </Button>
318	              </PopoverTrigger>
319	              <PopoverContent className="w-auto p-0">
320	                <CalendarComponent
321	                  mode="single"
322	                  selected={newFabricacao}
323	                  onSelect={setNewFabricacao}
324	                  initialFocus
325	                />
326	              </PopoverContent>
327	            </Popover>
328	            <Popover>
329	              <PopoverTrigger asChild>
330	                <Button
331	                  variant="outline"
332	                  className={cn(
333	                    'h-8 text-xs justify-start text-left font-normal',
334	                    !newValidade && 'text-muted-foreground',
335	                  )}
336	                >
337	                  <Calendar className="mr-2 h-3 w-3" />
338	                  {newValidade ? format(newValidade, 'dd/MM/yyyy') : 'Validade'}
339	                </Button>
340	              </PopoverTrigger>
341	              <PopoverContent className="w-auto p-0">
342	                <CalendarComponent
343	                  mode="single"
344	                  selected={newValidade}
345	                  onSelect={setNewValidade}
346	                  initialFocus
347	                />
348	              </PopoverContent>
349	            </Popover>
350	            <Input data-mia-field="new_qtd"
351	              type="number"
352	              placeholder="Qtd Inicial"
353	              value={newQtd}
354	              onChange={(e) => setNewQtd(e.target.value)}
355	              className="h-8 text-xs"
356	            />
357	          </div>
358	          <Button data-mia-action="add-batch"
359	            size="sm"
360	            onClick={handleAddBatch}
361	            className="w-full h-7 bg-[#57715B] text-white hover:bg-[#57715B]/90 text-xs"
362	          >
363	            Criar Lote e Adicionar ao Estoque
364	          </Button>
365	        </div>
366	      )}
367	
368	      <div className="space-y-2">
369	        {batches.length === 0 ? (
370	          <div className="text-center py-4 text-xs text-muted-foreground bg-black/5 rounded-lg border border-dashed border-black/10">
371	            Nenhum lote neste estoque.
372	          </div>
373	        ) : (
374	          batches.map((batch) => {
375	            const status = getExpiryStatus(batch.lotes.data_validade);
376	            const StatusIcon = status.icon;
377	            return (
378	              <div
379	                key={batch.id}
380	                className="flex flex-col sm:flex-row items-start sm:items-center justify-between p-3 bg-white/60 dark:bg-black/40 rounded-lg border border-[#57715B]/10 gap-3"
381	              >
382	                <div className="flex-1 space-y-1">
383	                  <div className="flex items-center gap-2">
384	                    <span className="font-mono font-bold text-sm text-foreground">
385	                      {batch.lotes.codigo}
386	                    </span>
387	                    <Badge
388	                      variant="outline"
389	                      className={cn(
390	                        'text-[10px] h-5 px-1.5 gap-1',
391	                        status.color,
392	                      )}
393	                    >
394	                      <StatusIcon className="w-3 h-3" />
395	                      Val:{' '}
396	                      {format(
397	                        parseISO(batch.lotes.data_validade),
398	                        'dd/MM/yyyy',
399	                      )}
400	                    </Badge>
401	                    {batch.lotes.data_fabricacao && (
402	                      <Badge
403	                        variant="outline"
404	                        className="text-[10px] h-5 px-1.5 gap-1 text-gray-500 border-gray-200"
405	                      >
406	                        Fab:{' '}
407	                        {format(
408	                          parseISO(batch.lotes.data_fabricacao),
409	                          'dd/MM/yyyy',
410	                        )}
411	                      </Badge>
412	                    )}
413	                  </div>
414	                  <div className="text-[10px] text-muted-foreground uppercase tracking-wider font-bold">
415	                    {status.label}
416	                  </div>
417	                </div>
418	
419	                <div className="flex items-center gap-3">
420	                  <div className="flex items-center gap-1 bg-white dark:bg-black rounded-lg border border-gray-200 dark:border-gray-800 p-0.5">
421	                    <Button
422	                      variant="ghost"
423	                      size="icon"
424	                      className="h-7 w-7 rounded-md hover:bg-gray-100 dark:hover:bg-gray-800"
425	                      onClick={() =>
426	                        adjustQuantity(
427	                          batch.id,
428	                          batch.quantidade,
429	                          -1,
430	                          batch.lote_id,
431	                        )
432	                      }
433	                    >
434	                      <Minus className="w-3 h-3" />
435	                    </Button>
436	                    <span className="w-12 text-center font-mono font-bold text-sm">
437	                      {batch.quantidade}
438	                    </span>
439	                    <Button
440	                      variant="ghost"
441	                      size="icon"
442	                      className="h-7 w-7 rounded-md hover:bg-gray-100 dark:hover:bg-gray-800"
443	                      onClick={() =>
444	                        adjustQuantity(
445	                          batch.id,
446	                          batch.quantidade,
447	                          +1,
448	                          batch.lote_id,
449	                        )
450	                      }
451	                    >
452	                      <Plus className="w-3 h-3" />
453	                    </Button>
454	                  </div>
455	                </div>
456	              </div>
457	            );
458	          })
459	        )}
460	      </div>
461	    </div>
462	  );
463	}
