1	import React, { useState, useEffect } from "react";
2	import { Plus, AlertTriangle, Calendar, Package } from "lucide-react";
3	import { Button } from "@/shared/ui/button";
4	import { Input } from "@/shared/ui/input";
5	import { Badge } from "@/shared/ui/badge";
6	import { Popover, PopoverContent, PopoverTrigger } from "@/shared/ui/popover";
7	import { Calendar as CalendarComponent } from "@/shared/ui/calendar";
8	import { format, addDays, parseISO } from "date-fns";
9	import { cn } from "@/shared/lib/utils";
10	import { supabase } from "@/integrations/supabase/client";
11	import { useToast } from "@/shared/hooks/use-toast";
12	import { handleError } from '@/shared/lib/error-handler';
13	
14	interface StockBatch {
15	    id: string; // lote_id
16	    codigo: string;
17	    data_validade: string;
18	    data_fabricacao: string | null;
19	}
20	
21	interface BatchListProps {
22	    produtoId: number;
23	    storeId: number;
24	    produtoNome: string;
25	    diasValidadePadrao?: number;
26	    onUpdate?: () => void;
27	}
28	
29	export function BatchList({ produtoId, storeId, produtoNome, diasValidadePadrao, onUpdate }: BatchListProps) {
30	    const [batches, setBatches] = useState<StockBatch[]>([]);
31	    const [loading, setLoading] = useState(false);
32	
33	    // New Batch Form
34	    const [newFabricacao, setNewFabricacao] = useState<Date | undefined>(new Date());
35	    const [newValidade, setNewValidade] = useState<Date | undefined>(
36	        diasValidadePadrao ? addDays(new Date(), diasValidadePadrao) : undefined
37	    );
38	    const [isAdding, setIsAdding] = useState(false);
39	
40	    const { toast } = useToast();
41	
42	    useEffect(() => {
43	        fetchBatches();
44	    }, [produtoId, storeId]);
45	
46	    useEffect(() => {
47	        if (newFabricacao && diasValidadePadrao) {
48	            setNewValidade(addDays(newFabricacao, diasValidadePadrao));
49	        }
50	    }, [newFabricacao, diasValidadePadrao]);
51	
52	    const fetchBatches = async () => {
53	        setLoading(true);
54	        try {
55	            const { data, error } = await supabase
56	                .from('lotes')
57	                .select(`
58	                    id,
59	                    codigo,
60	                    data_validade,
61	                    data_fabricacao
62	                `)
63	                .eq('produto_id', produtoId)
64	                .eq('loja_id', storeId);
65	
66	            if (error) throw error;
67	
68	            const sorted = ((data || []) as any[]).sort((a, b) => {
69	                // Sort by creation or validity? Let's sort by validity descending (newest expiry first)
70	                const dateA = new Date(a.data_validade).getTime();
71	                const dateB = new Date(b.data_validade).getTime();
72	                return dateB - dateA; // Descending
73	            });
74	
75	            setBatches(sorted);
76	
77	        } catch (error) {
78	            handleError(error, { domain: 'logistica', operation: 'fetchBatches', showToast: false });
79	        } finally {
80	            setLoading(false);
81	        }
82	    };
83	
84	    const handleAddBatch = async () => {
85	        if (!newFabricacao || !newValidade) {
86	            toast({ title: "Preencha todos os campos", variant: "destructive" });
87	            return;
88	        }
89	
90	        const fabricacaoStr = format(newFabricacao, 'ddMMyyyy');
91	        // Removed time from batch code to make it cleaner (requested by user)
92	        // Old format: L{ddMMyyyy}{HHmm} -> L270220261430
93	        // New format: L{ddMMyyyy} -> L27022026
94	        const generatedLoteCode = `L${fabricacaoStr}`;
95	
96	        try {
97	            // Criação idempotente: reaproveita o lote existente (mesmo produto+código)
98	            // em vez de criar um id divergente. Evita orfanizar etiquetas já impressas.
99	            const { error: loteError } = await (supabase.rpc as any)('find_or_create_lote', {
100	                p_produto_id: produtoId,
101	                p_codigo: generatedLoteCode,
102	                p_data_validade: format(newValidade, 'yyyy-MM-dd'),
103	                p_data_fabricacao: format(newFabricacao, 'yyyy-MM-dd'),
104	                p_loja_id: storeId,
105	            });
106	
107	            if (loteError) throw loteError;
108	
109	            // NÃO criar estoque_lotes com quantidade=0 na criação do lote.
110	            // O trigger sync_estoque_from_lotes calcula SUM(quantidade) e zeraria
111	            // o estoque existente. A row em estoque_lotes deve ser criada
112	            // apenas quando houver entrada real de quantidade (via bipe/recebimento).
113	            // Hardened 2026-05-20.
114	
115	            toast({ title: `Lote ${generatedLoteCode} criado com sucesso!` });
116	
117	            setNewFabricacao(new Date());
118	            setIsAdding(false);
119	
120	            fetchBatches();
121	            onUpdate?.();
122	
123	        } catch (e: any) {
124	            handleError(e, { domain: 'logistica', operation: 'addBatch', showToast: false });
125	            toast({
126	                title: "Erro ao criar lote",
127	                description: e.message || "Verifique os dados e tente novamente",
128	                variant: "destructive"
129	            });
130	        }
131	    };
132	
133	    // Lote é identidade permanente (produto + código + validade) e é referenciado
